use twostack_queue::Queue;

#[test]
fn test_basic_fifo() {
    let mut q: Queue<i32> = Queue::new();
    q.enqueue(1);
    q.enqueue(2);
    q.enqueue(3);
    assert_eq!(q.dequeue(), Some(1));
    assert_eq!(q.dequeue(), Some(2));
    assert_eq!(q.dequeue(), Some(3));
    assert_eq!(q.dequeue(), None);
}

#[test]
fn test_is_empty() {
    let mut q: Queue<u8> = Queue::new();
    assert!(q.is_empty());
    q.enqueue(1);
    assert!(!q.is_empty());
    q.dequeue();
    assert!(q.is_empty());
}

#[test]
fn test_len() {
    let mut q: Queue<&str> = Queue::new();
    assert_eq!(q.len(), 0);
    q.enqueue("a");
    q.enqueue("b");
    assert_eq!(q.len(), 2);
    q.dequeue();
    assert_eq!(q.len(), 1);
}

#[test]
fn test_peek() {
    let mut q: Queue<i32> = Queue::new();
    assert_eq!(q.peek(), None);
    q.enqueue(10);
    q.enqueue(20);
    assert_eq!(q.peek(), Some(&10));
    q.dequeue();
    assert_eq!(q.peek(), Some(&20));
}

#[test]
fn test_interleaved() {
    let mut q: Queue<i32> = Queue::new();
    q.enqueue(1);
    q.enqueue(2);
    assert_eq!(q.dequeue(), Some(1));
    q.enqueue(3);
    assert_eq!(q.dequeue(), Some(2));
    assert_eq!(q.dequeue(), Some(3));
}
